mapper.select:
select id, is_deleted, nezha_tenant_code, name, description, status, agent_def_id, behavior_dsl, model_config, business_rules, skill_ids, version, publish_status, last_publish_at, last_publish_by, create_at, create_by, create_name, update_at, update_by, update_name from agent_definition where is_deleted = 0
and name like concat('%', #{name,jdbcType=VARCHAR}, '%')
and status = #{status,jdbcType=VARCHAR}
and publish_status = #{publishStatus,jdbcType=VARCHAR}
order by id desc
